ROB = {'robuste': 'etabli', 'modere': 'estimation', 'controverse': 'debat', 'hypothese': 'interpretation'}

def fait(texte, source, periode, perimetre, explication, fiabilite='etabli', chiffre=None):
    d = dict(fait=texte, periode=periode, perimetre=perimetre, explication=explication, source=source, fiabilite=fiabilite)
    if chiffre: d['chiffre'] = chiffre
    return d

def fiche(id, affirmation, robustesse, resume, contexte, explication, sources, faits, court, moyen, detaille, empathie, application, contre, questions, limites, mots_cles, verdict=None):
    idx = {k: i for i, k in enumerate(sources)}
    return dict(
        id=id, type='science', affirmation=affirmation, volet='autre', sous_theme=None, rubriques=['science-du-dialogue'],
        mots_cles=mots_cles, verdict=verdict, fiabilite=ROB[robustesse], stabilite='evolutive', robustesse=robustesse,
        resume=resume, contexte=contexte, explication=explication,
        faits=[{**f, 'source': idx[f['source']]} for f in faits],
        argumentaires=dict(court=court, moyen=moyen, detaille=detaille, empathie=empathie),
        application=[dict(situation=s, tactique=t) for s, t in application],
        contre_arguments=[dict(objection=o, reponse=r) for o, r in contre],
        questions=questions, limites=limites + ["Les éléments de contexte historique (origine et date des théories) relèvent de connaissances générales et ne sont pas sourcés individuellement."], sources=[S[k] for k in sources],
        derniere_verification=TODAY, a_actualiser_le='2028-10-29',
        raison_actualisation="Bibliothèque scientifique : vérifier les nouvelles méta-analyses et réplications.",
    )

